const main=document.querySelector('#main');
let observationCount=3;
document.documentElement.dataset.theme='research';
const arrow='<span class="round-arrow" aria-hidden="true">↗</span>';
const thoughtHeadline=profile.questionFirst+'<br>'+profile.questionSecond;
const graphMarkup=`<svg class="chart" viewBox="0 0 400 170" role="img" aria-label="正态分布示意：增加观察后，后验分布逐渐收窄"><defs><linearGradient id="curve-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c6f38a" stop-opacity=".28"/><stop offset="1" stop-color="#c6f38a" stop-opacity="0"/></linearGradient></defs><path d="M12 145H388" fill="none" stroke="#48533e"/><path d="M106 141v8M200 141v8M294 141v8" stroke="#48533e"/><path class="prior-path" fill="none" stroke="#7c8a6f" stroke-dasharray="4 5" stroke-width="1.5"/><path class="area-path" fill="url(#curve-fill)"/><path class="posterior-path" fill="none" stroke="#c6f38a" stroke-width="2.5"/><text x="106" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">−2</text><text x="200" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">0</text><text x="294" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">2</text></svg>`;
function controls(){return `<div class="graph-footer"><div class="chart-legend"><span>先验</span><span>后验</span></div><div class="evidence-controls"><button class="evidence-reset" aria-label="重置概率实验" title="重置">↺</button><button class="evidence-add">＋ 一条证据</button></div></div><div class="graph-caption"><span class="sample-count" aria-live="polite">OBSERVATIONS / 03</span><span>P(H | D) ∝ P(D | H) P(H)</span></div>`}
function home(){return `<div class="intro-line"><span class="eyebrow">01 / A MIND IN PROGRESS</span><span>研究问题先行，证据随后。<span aria-hidden="true"> ↙</span></span></div><div class="bento-grid page-enter">
<section class="card hero"><div class="hero-top"><span class="eyebrow">LOGIC · MATHEMATICS · STATISTICS</span><span class="micro-tag">HELLO, WORLD</span></div><h1>从复杂中，<br>看见<span>结构。</span></h1><p class="hero-description">${profile.bio}</p><div class="hero-bottom"><div class="hero-name">Yuanshu Wang<small>${profile.identity}</small></div><a class="text-link" href="#/background">进一步认识我 ${arrow}</a></div></section>
<section class="card probability"><div class="card-heading"><span class="eyebrow">A SMALL THOUGHT EXPERIMENT</span><span class="small-tag">可交互</span></div><h2 class="graph-title">多一点证据，<br><em>少一点不确定。</em></h2>${graphMarkup}${controls()}</section>
<section class="card skills" aria-label="核心强项"><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">⊢</span><div><h2>逻辑推演</h2><p>REASON FROM FIRST PRINCIPLES</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">∫</span><div><h2>数学建模</h2><p>FIND THE UNDERLYING STRUCTURE</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">σ</span><div><h2>统计推断</h2><p>MAKE SENSE OF UNCERTAINTY</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a></section>
<a class="card thoughts card-link" href="#/thoughts"><div class="card-heading"><span class="eyebrow">CURRENTLY ON MY MIND</span><span class="small-tag">${profile.questionStatus}</span></div><h2>${thoughtHeadline}</h2><div class="thoughts-bottom"><p>${profile.questionCaption}</p>${arrow}</div></a>
<a class="card quant card-link" href="#/quant"><span class="eyebrow">SIGNAL / NOISE</span><h2>关于量化。</h2><p>${profile.quantCaption}</p><svg class="signal-chart" viewBox="0 0 400 75" aria-hidden="true"><path d="M0 40H400" stroke="#384332" stroke-dasharray="3 6"/><path class="noise-path" fill="none" stroke="#677a54" stroke-width="1"/><path class="signal-path" fill="none" stroke="#c6f38a" stroke-width="2"/></svg><div class="card-bottom"><span class="eyebrow">MODELS ARE A LENS, NOT THE WORLD</span>${arrow}</div></a>
<a class="card background card-link" href="#/background"><span class="eyebrow">THE PERSON BEHIND</span><span class="mini-math" aria-hidden="true">x → f(x)</span><h2 class="lower-title">我的来路。</h2><p class="lower-copy">${profile.backgroundCaption}</p><div class="card-bottom"><span class="eyebrow">BACKGROUND & EXPERIENCE</span>${arrow}</div></a>
<a class="card philosophy card-link" href="#/philosophy"><span class="eyebrow">WAYS OF SEEING</span><span class="mini-math" aria-hidden="true">∴ &nbsp; ?</span><h2 class="lower-title">思考的底层。</h2><p class="lower-copy">${profile.philosophyCaption}</p><div class="card-bottom"><span class="eyebrow">PHILOSOPHY & BELIEFS</span>${arrow}</div></a>
<a class="card lab card-link" href="#/lab"><span class="eyebrow">WHERE IDEAS BECOME REAL</span><span class="lab-symbol" aria-hidden="true">[ ↗ ]</span><h2 class="lower-title">AI 实验室。</h2><p class="lower-copy">${profile.labCaption}</p><div class="card-bottom"><span class="eyebrow">EXPERIMENTS & CREATIONS</span>${arrow}</div></a>
<section class="card social-row"><div class="social-heading">在别处找到我<span>让对话继续。</span></div><div class="social-links"><button data-social="LinkedIn">LinkedIn <span>↗</span></button><button data-social="GitHub">GitHub <span>↗</span></button><button data-social="Email">Email <span>↗</span></button></div></section></div>`}
const pages=profilePages;
function detail(route) {
  const p=pages[route];
  return `<div class="page-enter">
    <div class="detail-top"><a class="back-link" href="#/">← 返回概览</a><span class="eyebrow">${p.number} / PERSONAL INDEX</span></div>
    <header class="detail-hero"><span class="eyebrow">${p.eyebrow}</span><h1>${p.title}</h1><p>${p.subtitle}</p><div class="draft-note">${p.intro}</div></header>
    <div class="detail-grid">${p.sections.map(s=>`<section class="card detail-card"><span class="detail-num">${s[0]}</span><h2>${s[1]}</h2><p>${s[2]}</p><div class="detail-body"><p>${s[3]}</p></div></section>`).join('')}
    ${p.wide?`<section class="card detail-wide"><span class="eyebrow">ROOM FOR MORE</span><h2>${p.wide[0]}</h2><p>${p.wide[1]}</p></section>`:''}</div>
    <nav class="detail-related" aria-label="继续探索">${p.related.map(r=>`<a href="#/${r[0]}">${r[1]} ↗</a>`).join('')}</nav>
  </div>`;
}
function lab() {
  return `<div class="page-enter">
    <div class="detail-top"><a class="back-link" href="#/">← 返回概览</a><span class="eyebrow">07 / PERSONAL INDEX</span></div>
    <header class="detail-hero"><span class="eyebrow">IDEAS, MADE TANGIBLE</span><h1>好奇心的实验场。</h1><p>${profile.labSubtitle}</p><div class="draft-note">${profile.labIntro}</div></header>
    <div class="project-section-heading"><h2>${profile.labLabel}</h2><span class="eyebrow">${profile.projectLinks}</span></div>
    <div class="detail-grid lab-projects">${researchProjects.map(p=>`<section class="card detail-card"><span class="detail-num">${p.number} / <span>${p.category}</span></span><h2>${p.title}</h2><p>${p.description}</p><details class="project-focus"><summary>${profile.projectDetail}</summary><p>${p.focus}</p></details></section>`).join('')}</div>
    <div class="project-section-heading experiment-heading"><h2>${profile.demoLabel}</h2></div>
    <section class="card full-experiment"><div><span class="eyebrow">00 / AN INTERACTIVE SKETCH</span><h2>证据如何改变判断？</h2><p class="experiment-explanation">点击「一条证据」，观察先验如何更新为后验。这个小实验用正态模型，展示判断随观察增加而收窄的过程。</p><div class="formula">P(H | D) ∝ P(D | H) · P(H)</div><p class="experiment-explanation">演示假设：先验 N(0, 1)，每次独立观察值固定为 0.65，观测标准差 0.8。为方便比较，曲线使用相同的纵轴尺度；它是一个受控示例。</p><span class="small-tag">本站互动示例 · 非个人作品履历</span></div><div>${graphMarkup}${controls()}</div></section>
    <nav class="detail-related" aria-label="继续探索"><a href="#/thoughts">当前想法 ↗</a><a href="#/quant">关于量化 ↗</a></nav>
  </div>`;
}
function render(){const requested=location.hash.replace(/^#\/?/,'')||'home';const route=requested==='lab'||Object.hasOwn(pages,requested)?requested:'home';main.innerHTML=route==='home'?home():route==='lab'?lab():detail(route);document.title=(route==='home'?'Yuanshu Wang':route==='lab'?'AI 实验室':pages[route].title)+' — Signal & Structure';document.querySelectorAll('[data-nav]').forEach(a=>{const active=route==='home'?'home':route==='lab'?'lab':['thoughts','philosophy','quant'].includes(route)?'thoughts':null;if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});wire();localize();document.title=translateCopy(route==='home'?'Yuanshu Wang':route==='lab'?'AI 实验室':pages[route].title)+' — Signal & Structure';}
function wire(){let count=observationCount;const curve=(mu,sigma)=>Array.from({length:241},(_,i)=>{const x=-4+i/30;return [(12+(x+4)*47).toFixed(2),(145-80*Math.exp(-.5*((x-mu)/sigma)**2)/(sigma*Math.sqrt(2*Math.PI))).toFixed(2)]});const path=points=>'M'+points.map(p=>p.join(' ')).join('L');function redraw(){observationCount=count;const variance=.64/(.64+count);const posterior=curve(count*.65/(.64+count),Math.sqrt(variance));document.querySelectorAll('.prior-path').forEach(e=>e.setAttribute('d',path(curve(0,1))));document.querySelectorAll('.posterior-path').forEach(e=>e.setAttribute('d',path(posterior)));document.querySelectorAll('.area-path').forEach(e=>e.setAttribute('d',path(posterior)+'L388 145L12 145Z'));document.querySelectorAll('.sample-count').forEach(e=>e.textContent='OBSERVATIONS / '+String(count).padStart(2,'0'));document.querySelectorAll('.evidence-add').forEach(e=>{e.disabled=count>=10;e.textContent=count>=10?'已观察 10 次':'＋ 一条证据'});localize();}document.querySelectorAll('.evidence-add').forEach(e=>e.addEventListener('click',()=>{count=Math.min(count+1,10);redraw()}));document.querySelectorAll('.evidence-reset').forEach(e=>e.addEventListener('click',()=>{count=0;redraw()}));redraw();const points=Array.from({length:101},(_,i)=>{let x=i*4,y=40-11*Math.sin(i*.085)-5*Math.cos(i*.14);return {x,y,noise:y+10*Math.sin(i*2.31)+6*Math.cos(i*3.65)}});document.querySelectorAll('.signal-path').forEach(e=>e.setAttribute('d','M'+points.map(p=>p.x+','+p.y.toFixed(2)).join('L')));document.querySelectorAll('.noise-path').forEach(e=>e.setAttribute('d','M'+points.map(p=>p.x+','+p.noise.toFixed(2)).join('L')));document.querySelectorAll('[data-social]').forEach(e=>e.addEventListener('click',()=>{document.querySelector('#link-title').textContent=e.dataset.social;localize();document.querySelector('#link-dialog').showModal()}));}
document.querySelector('#year').textContent=new Date().getFullYear();window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return}render();window.scrollTo(0,0);main.focus({preventScroll:true})});render();
